package com.retail.catalog;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.transaction.annotation.Transactional;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import com.retail.common.audit.AuditService;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.bind.annotation.*;
import com.retail.common.security.BranchAccess;
import com.retail.branches.BranchEntity;
import com.retail.branches.BranchRepository;
@RestController @RequestMapping("/api/v1")
public class DirectoryController {
 private final JdbcTemplate jdbc; private final BranchAccess access; private final BranchRepository branchRepository; private final AuditService audit;
 public record BranchUpdate(@NotBlank @Size(max=30) String code,@NotBlank @Size(max=120) String name,@Size(max=4000) String address){}
 public record ActiveUpdate(@NotNull Boolean active){}
 public record UnitCreate(@NotBlank @Size(max=20) String code,@NotBlank @Size(max=80) String name){}
 private final Map<String,String> queries=Map.ofEntries(
  Map.entry("branches","select id,code,name,address,active from branches order by name"),Map.entry("categories","select id,name,parent_id,active from categories order by name"),Map.entry("brands","select id,name,active from brands order by name"),Map.entry("units","select id,code,name from units order by name"),Map.entry("customers","select id,code,name,phone,email,active from customers order by name"),Map.entry("suppliers","select id,code,name,phone,email,active from suppliers order by name"),Map.entry("users","select id,username,display_name,active,created_at from users order by display_name"),Map.entry("roles","select id,code,name from roles order by name"),Map.entry("permissions","select p.id,p.code,p.description,r.code role_code from permissions p left join role_permissions rp on rp.permission_id=p.id left join roles r on r.id=rp.role_id order by p.code,r.code"),Map.entry("inventory/balances","select sb.location_id,l.name location_name,l.branch_id,sb.product_id,p.sku,p.name product_name,sb.quantity,p.reorder_level from stock_balances sb join locations l on l.id=sb.location_id join products p on p.id=sb.product_id order by p.name"),Map.entry("inventory/movements","select sm.id,sm.product_id,p.sku,p.name product_name,sm.location_id,l.name location_name,sm.quantity_delta,sm.movement_type,sm.source_type,sm.created_at from stock_movements sm join products p on p.id=sm.product_id join locations l on l.id=sm.location_id order by sm.created_at desc limit 200"),Map.entry("sales","select s.id,s.invoice_no,s.branch_id,b.name branch_name,s.currency_code,s.total,s.status,s.completed_at from sales s join branches b on b.id=s.branch_id order by s.completed_at desc limit 200"),Map.entry("purchases","select po.id,po.order_no,po.supplier_id,s.name supplier_name,po.status,po.currency_code,po.created_at from purchase_orders po join suppliers s on s.id=po.supplier_id order by po.created_at desc"),Map.entry("transfers","select t.id,t.transfer_no,t.source_location_id,t.destination_location_id,sl.branch_id source_branch_id,dl.branch_id destination_branch_id,t.status,t.created_at,t.dispatched_at,t.received_at from stock_transfers t join locations sl on sl.id=t.source_location_id join locations dl on dl.id=t.destination_location_id order by t.created_at desc"),Map.entry("audit","select id,actor_id,action,entity_type,entity_id,branch_id,created_at from audit_events order by created_at desc limit 200")
 );
 public DirectoryController(JdbcTemplate jdbc,BranchAccess access,BranchRepository branchRepository,AuditService audit){this.jdbc=jdbc;this.access=access;this.branchRepository=branchRepository;this.audit=audit;}
 @GetMapping("/{resource:branches|categories|brands|units|customers|suppliers|users|roles|permissions|inventory|transfers|sales|purchases|audit}") public Map<String,Object> list(@PathVariable String resource,Authentication auth){String key=resource;if(resource.equals("inventory"))key="inventory/balances";if(resource.equals("branches")){var rows=access.global(auth)?branchRepository.findAll():branchRepository.findAllById(access.branches(auth));return Map.of("items",rows);}String sql=queries.get(key);if(sql==null)throw new IllegalArgumentException("Unknown resource");if(Set.of("users","roles","permissions","audit").contains(key)&&!access.global(auth))throw new org.springframework.security.access.AccessDeniedException("Administrator access required");var ids=access.branches(auth);if(!access.global(auth)&&key.equals("customers")){if(ids.isEmpty())return Map.of("items",List.of());String customerSql="select id,code,name,phone,email,active from customers where branch_id in ("+String.join(",",Collections.nCopies(ids.size(),"?"))+") order by name";return Map.of("items",jdbc.queryForList(customerSql,ids.toArray()));}if(!access.global(auth)&&key.equals("branches")){if(ids.isEmpty())return Map.of("items",List.of());sql=sql.replace(" order by", " where id in ("+String.join(",",Collections.nCopies(ids.size(),"?"))+") order by");return Map.of("items",jdbc.queryForList(sql,ids.toArray()));}if(!access.global(auth)&&key.equals("purchases")&&auth.getAuthorities().stream().noneMatch(x->x.getAuthority().equals("ROLE_INVENTORY_STAFF")))throw new org.springframework.security.access.AccessDeniedException("Warehouse purchase access required");if(!access.global(auth)&&key.equals("transfers")){if(ids.isEmpty())return Map.of("items",List.of());sql=sql.replace(" order by", " where sl.branch_id in ("+String.join(",",Collections.nCopies(ids.size(),"?"))+") or dl.branch_id in ("+String.join(",",Collections.nCopies(ids.size(),"?"))+") order by");var params=new ArrayList<UUID>(ids);params.addAll(ids);return Map.of("items",jdbc.queryForList(sql,params.toArray()));}if(!access.global(auth)&&key.equals("sales")){if(ids.isEmpty())return Map.of("items",List.of());sql=sql.replace(" order by", " where s.branch_id in ("+String.join(",",Collections.nCopies(ids.size(),"?"))+") order by");return Map.of("items",jdbc.queryForList(sql,ids.toArray()));}if(!access.global(auth)&&key.equals("inventory/balances")){if(ids.isEmpty())return Map.of("items",List.of());sql=sql.replace(" order by", " where l.branch_id in ("+String.join(",",Collections.nCopies(ids.size(),"?"))+") order by");return Map.of("items",jdbc.queryForList(sql,ids.toArray()));}return Map.of("items",jdbc.queryForList(sql));}
 @GetMapping("/locations") public Map<String,Object> locations(Authentication auth){var ids=access.branches(auth);if(access.global(auth))return Map.of("items",jdbc.queryForList("select id,code,name,type,branch_id from locations where active=true order by type,name"));if(ids.isEmpty())return Map.of("items",List.of());String marks=String.join(",",Collections.nCopies(ids.size(),"?"));return Map.of("items",jdbc.queryForList("select id,code,name,type,branch_id from locations where active=true and (branch_id in ("+marks+") or type in ('CENTRAL_WAREHOUSE','IN_TRANSIT')) order by type,name",ids.toArray()));}
 @GetMapping("/inventory/balances") public Map<String,Object> balances(Authentication auth){String sql=queries.get("inventory/balances");var ids=access.branches(auth);if(!access.global(auth)){if(ids.isEmpty())return Map.of("items",List.of());sql=sql.replace(" order by", " where l.branch_id in ("+String.join(",",Collections.nCopies(ids.size(),"?"))+") order by");return Map.of("items",jdbc.queryForList(sql,ids.toArray()));}return Map.of("items",jdbc.queryForList(sql));}
 @PostMapping("/branches") @Transactional @PreAuthorize("hasRole('SUPER_ADMIN')") public Map<String,Object> createBranch(@RequestBody Map<String,String> body){UUID id=UUID.randomUUID();jdbc.update("insert into branches(id,code,name,address) values (?,?,?,?)",id,required(body,"code"),required(body,"name"),body.get("address"));jdbc.update("insert into locations(code,name,type,branch_id) values (?,?,'BRANCH',?)",body.get("code"),body.get("name"),id);return Map.of("id",id,"code",body.get("code"),"name",body.get("name"));}
 @PutMapping("/branches/{id}") @Transactional @PreAuthorize("hasRole('SUPER_ADMIN')") public Map<String,Object> updateBranch(@PathVariable UUID id,@Valid @RequestBody BranchUpdate request,Authentication auth){
  var branch=jdbc.queryForList("select id from branches where id=? for update",id);if(branch.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Branch not found");
  jdbc.update("update branches set code=?,name=?,address=?,updated_at=now() where id=?",request.code().trim(),request.name().trim(),request.address(),id);
  jdbc.update("update locations set code=?,name=? where branch_id=? and type='BRANCH'",request.code().trim(),request.name().trim(),id);
  audit.record(username(auth),"BRANCH_UPDATED","BRANCH",id,null);
  return Map.of("id",id,"code",request.code().trim(),"name",request.name().trim(),"address",request.address()==null?"":request.address());
 }
 @PatchMapping("/branches/{id}/status") @Transactional @PreAuthorize("hasRole('SUPER_ADMIN')") public Map<String,Object> branchStatus(@PathVariable UUID id,@Valid @RequestBody ActiveUpdate request,Authentication auth){
  var rows=jdbc.queryForList("select active from branches where id=? for update",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Branch not found");boolean active=request.active();
  if(!active){
   int assigned=jdbc.queryForObject("select count(*) from user_branches ub join users u on u.id=ub.user_id where ub.branch_id=? and u.active=true",Integer.class,id);
   int stock=jdbc.queryForObject("select count(*) from stock_balances sb join locations l on l.id=sb.location_id where l.branch_id=? and sb.quantity>0",Integer.class,id);
   int transfers=jdbc.queryForObject("select count(*) from stock_transfers t join locations l on l.id=t.source_location_id or l.id=t.destination_location_id where l.branch_id=? and t.status in ('PENDING','APPROVED','IN_TRANSIT')",Integer.class,id);
   if(assigned>0||stock>0||transfers>0)throw new IllegalStateException("Branch has active users, stock, or open transfers and cannot be deactivated");
  }
  jdbc.update("update branches set active=?,updated_at=now() where id=?",active,id);jdbc.update("update locations set active=? where branch_id=? and type='BRANCH'",active,id);
  audit.record(username(auth),active?"BRANCH_ACTIVATED":"BRANCH_DEACTIVATED","BRANCH",id,null);
  return Map.of("id",id,"active",active);
 }
 @PostMapping("/categories") @PreAuthorize("hasAnyRole('SUPER_ADMIN','BRANCH_MANAGER')") public Map<String,Object> category(@RequestBody Map<String,String> body){UUID id=UUID.randomUUID();jdbc.update("insert into categories(id,name) values (?,?)",id,required(body,"name"));return Map.of("id",id,"name",body.get("name"));}
 @PostMapping("/brands") @PreAuthorize("hasAnyRole('SUPER_ADMIN','BRANCH_MANAGER')") public Map<String,Object> brand(@RequestBody Map<String,String> body){UUID id=UUID.randomUUID();jdbc.update("insert into brands(id,name) values (?,?)",id,required(body,"name"));return Map.of("id",id,"name",body.get("name"));}
 @PostMapping("/units") @PreAuthorize("hasRole('SUPER_ADMIN')") public Map<String,Object> unit(@Valid @RequestBody UnitCreate request){UUID id=UUID.randomUUID();jdbc.update("insert into units(id,code,name) values (?,?,?)",id,request.code().trim(),request.name().trim());return Map.of("id",id,"code",request.code().trim(),"name",request.name().trim());}
 @PostMapping("/customers") @PreAuthorize("hasAnyRole('SUPER_ADMIN','BRANCH_MANAGER','CASHIER')") public Map<String,Object> customer(@RequestBody Map<String,String> body,Authentication auth){UUID id=UUID.randomUUID();UUID branch=null;if(body.get("branchId")!=null&&!body.get("branchId").isBlank())branch=UUID.fromString(body.get("branchId"));else if(!access.global(auth)){var assigned=access.branches(auth);if(assigned.isEmpty())throw new org.springframework.security.access.AccessDeniedException("Branch assignment required");branch=assigned.getFirst();}if(branch!=null)access.requireBranch(auth,branch);jdbc.update("insert into customers(id,code,name,phone,email,branch_id) values (?,?,?,?,?,?)",id,body.getOrDefault("code",id.toString().substring(0,8)),required(body,"name"),body.get("phone"),body.get("email"),branch);return Map.of("id",id,"name",body.get("name"));}
 @PostMapping("/suppliers") @PreAuthorize("hasAnyRole('SUPER_ADMIN','BRANCH_MANAGER','INVENTORY_STAFF')") public Map<String,Object> supplier(@RequestBody Map<String,String> body){UUID id=UUID.randomUUID();jdbc.update("insert into suppliers(id,code,name,phone,email) values (?,?,?,?,?)",id,body.getOrDefault("code",id.toString().substring(0,8)),required(body,"name"),body.get("phone"),body.get("email"));return Map.of("id",id,"name",body.get("name"));}
 private String required(Map<String,String> b,String k){String v=b.get(k);if(v==null||v.isBlank())throw new IllegalArgumentException(k+" is required");return v.trim();}
 private String username(Authentication auth){var current=auth==null?SecurityContextHolder.getContext().getAuthentication():auth;if(current==null)throw new org.springframework.security.access.AccessDeniedException("Authenticated user is required");return current.getName();}
}







